from dog_lib import *
# ---------------- tissue scenes: nodes for what the scenes show ----------------
SK_ = [A('5.1', '5-1-layers-of-the-skin')]
N('dog_skin_scene', 'Inside a dog\'s skin and coat', 'tissue', 1e-3, ['dog_coat'], 'A slice through the skin shows the thin outer layer, the thick dermis, the fat below, and the hair follicles that grow the double coat.',
  'This is a schematic drawn from what is known about how dog skin is built. Hair roots sit in the dermis; a thick guard hair and a tuft of finer hairs leave through the same opening. Click a layer to read about it.',
  'The skin has three layers: a thin epidermis on top, the dermis with the follicles and glands, and fatty tissue below. A dog\'s follicles are compound: one big hair and a tuft of smaller ones share one opening.',
  'Every size in the scene is illustrative: no measured hair diameters, follicle depths or layer thicknesses were found. What is real is the arrangement.', [['Layers', 'epidermis, dermis, subcutis']], cert='C2', refs=SK_, ext=[MERCK_SKIN, SCLIP], human=[('skin', 'In people: the same three layers.')])
N('dog_skin_epidermis', 'Epidermis and the skin barrier', 'tissue', 1e-4, ['dog_skin_scene'], 'The outer skin is a thin layer of cells that die and flatten into a waterproof barrier.',
  'Cells are made at the bottom of the epidermis and move up as they fill with keratin and die. The top layer, the stratum corneum, is like roof tiles glued with fat. This keeps water in and germs out.',
  'The glue between the dead cells is a mixture of lipids: ceramides, cholesterol and free fatty acids. In dogs with atopic dermatitis these lipids are reduced. Press the button to see one of them, cholesterol.',
  'Dog stratum corneum lipid levels have been measured in atopic and healthy dogs; this card quotes only the composition, not amounts.', [['Barrier lipids', 'ceramides, cholesterol, free fatty acids']], cert='C2', refs=SK_, ext=[SCLIP], human=[('epidermis', 'In people: the same layers and the same kind of lipids.'), ('keratinocyte', 'Compare the human keratinocyte.')])
N('dog_skin_dermis', 'Dermis', 'tissue', 1e-3, ['dog_skin_scene'], 'The dermis is the tough, flexible layer under the epidermis that holds the follicles, glands, blood vessels and nerves.', 'It is made mostly of collagen fibres. It gives the skin strength and holds the hair roots.', 'The same tissue as in people.', 'Not drawn in detail.', [['Main component', 'collagen']], cert='C2', refs=SK_, human=[('dermis', 'In people: the same layer.')])
N('dog_follicle', 'Compound hair follicle', 'structure', 5e-4, ['dog_skin_scene'], 'One opening, many hairs: a dog\'s follicle grows a thick guard hair and a tuft of fine undercoat hairs together.',
  'In a Labrador the hairs come out in small groups. The big one (the guard hair) sheds water; the fine ones make a warm, soft felt.', 'Each follicle has a root bulb where cells divide, a sebaceous gland that oils the hair, and a scent-type (apocrine) gland. The follicle cycles between growth, rest and shedding. About 3-15 smaller hairs join one central hair.', 'Puppies start with simple follicles that become compound.', [['Smaller hairs per central hair', '≈ 3-15']], cert='C2', refs=[A('5.2', '5-2-accessory-structures-of-the-skin')], ext=[MERCK_SKIN], human=[('hair_follicle', 'In people: simple follicles, one hair each.')])
N('dog_undercoat', 'Undercoat', 'structure', .01, ['dog_coat'], 'The undercoat is the soft, fine layer of hair under the guard hairs.', 'It traps a layer of air, so it insulates. It is shed heavily in spring and autumn.', 'These are the secondary hairs of each compound follicle.', 'Not drawn separately on the model.', [['Role', 'insulation']], cert='C1', ext=[MERCK_SKIN, AKC])
N('dog_gland', 'Skin glands', 'structure', 5e-4, ['dog_skin_scene'], 'Two kinds of gland open into the follicles: oil glands and scent glands; the true sweat glands are only on the paw pads.',
  'The oil from sebaceous glands waterproofs hair. Scent glands (apocrine) are attached to follicles and make secretions that carry a dog\'s smell.', 'Because the body skin has no true sweat glands, dogs cannot cool by sweating; they pant.', 'The gland sizes and positions are schematic.', [['True sweat glands', 'paw pads only']], cert='C2', ext=[MERCK_SKIN], human=[('sweat_gland', 'In people: sweat glands all over the skin; the main way people cool.')])
N('dog_olfactory_epithelium', 'Inside the smell lining', 'tissue', 1e-4, ['dog_turb_olf'], 'A slice of the smell lining: sensing cells reach to the surface with tiny hairs that catch odour molecules, held up by supporting cells.',
  'Smell cells are nerve cells. Each has a tuft of hair-like cilia in the mucus at the surface. When an odour molecule fits a receptor on a cilium, the cell sends a signal along its thread (the axon) to the brain. Click a part.',
  'The lining has three kinds of cell: smell neurons, supporting cells and stem cells at the bottom that replace the neurons. The glands in the layer below make the mucus.', 'All sizes are illustrative: no measured dog cell dimensions were found. The layers and cell types are as in a mammal\'s smell lining.', [['Cell types', 'smell neurons, supporting cells, basal (stem) cells']], cert='C2', refs=[R('36.3', '36-3-taste-and-smell')], ext=[OSM363, WOR], human=[('nose_airway', 'In people: the same layers on a smaller patch.')])
N('dog_osn', 'Olfactory sensory neuron', 'tissue', 1e-5, ['dog_olfactory_epithelium'], 'A smell cell is a nerve cell that senses odour molecules with receptors on its cilia and sends the signal to the brain.',
  'Each smell cell carries one type of receptor. Odour molecules dissolve in the mucus, fit a receptor and trigger a signal. Press the button to see the molecule that carries the message inside the cell.',
  'When an odour binds the receptor, the receptor activates a G protein that turns on an enzyme (adenylyl cyclase). The enzyme makes cyclic AMP (cAMP) from ATP, cAMP opens channels in the cilium that let calcium and sodium in, and the cell fires. A dog has about 800 working receptor genes, a person about 400.',
  'Smell cells are replaced throughout life from the stem cells at the base of the lining. Each cell expresses one receptor gene out of the many; how a cell chooses one is a research question.', [['Receptor genes (functional)', '≈ 800 dog, ≈ 400 human'], ['Messenger', 'cAMP (cyclic AMP)']], cert='C1', refs=[R('36.3', '36-3-taste-and-smell')], ext=[WOR, QUIG], human=[('neuron', 'In people: the same type of neuron.')], openq=['How does each smell cell pick just one of its several hundred receptor genes? This is still being studied.'])
N('dog_sustentacular', 'Supporting (sustentacular) cells', 'tissue', 1e-5, ['dog_olfactory_epithelium'], 'Tall supporting cells hold the smell neurons in place and help clean the surface.', 'They stand among the smell neurons like pillars.', 'They also help protect and nourish the neurons.', 'Not drawn in fine detail.', [['Role', 'support']], cert='C2', ext=[WOR])
N('dog_basal', 'Basal (stem) cells', 'tissue', 1e-5, ['dog_olfactory_epithelium'], 'Small stem cells at the bottom of the lining make new smell neurons to replace old ones.', 'Smell neurons wear out and are replaced. The new ones grow from these stem cells.', 'They are one of the few places where new neurons are made in an adult mammal.', 'Not drawn in fine detail.', [['Role', 'replace smell neurons']], cert='C2', ext=[WOR], human=[('stem_cell', 'Compare the human stem cell.')])
N('dog_bowman', 'Bowman\'s glands (mucus)', 'tissue', 1e-4, ['dog_olfactory_epithelium'], 'Glands under the lining make the mucus in which smell molecules dissolve.', 'The mucus covers the cilia. Odour molecules must dissolve in it to reach receptors.', 'Mucus is also a protective barrier.', 'Not drawn in detail.', [['Role', 'mucus']], cert='C2', ext=[WOR])
N('dog_axons', 'Smell nerve fibres', 'tissue', 1e-5, ['dog_olfactory_epithelium'], 'The thin threads of the smell neurons leave the lining and pass through holes in the skull to the olfactory bulbs.', 'These threads carry the signals to the brain.', 'The threads pass through a sieve-like plate of bone (the cribriform plate).', 'Not drawn in detail.', [['Destination', 'olfactory bulbs']], cert='C2', ext=[WOR], human=[('peripheral_nerves', 'In people: the same pathway.')])
N('dog_muscle_scene', 'Inside a dog muscle', 'tissue', 1e-3, ['dog_muscles'], 'A bundle of muscle fibres: each is one long cell, with nerves and blood vessels running between them.',
  'A muscle is a bundle of bundles. Each fibre is a single cell, many nuclei long, packed with contracting threads. Nerves tell it to contract; capillaries bring oxygen. Click a fibre.',
  'The fibre widths in the scene are drawn from a measured average cross-section of dog thigh muscle fibres (about 1,700-1,800 µm², or about 47 µm across if round). Everything else is illustrative.', 'Fibre types (slow I, fast IIA, IIX) did not differ in size in the study cited.', [['Fibre cross-section', '≈ 1,700-1,800 µm² (vastus lateralis)'], ['Equivalent diameter (calculated)', '≈ 47 µm']], cert='C2', refs=[A('10.2', '10-2-skeletal-muscle')], ext=[MUSC_ARC], human=[('skeletal_muscle_tissue', 'In people: the same tissue.')])
N('dog_muscle_fibre', 'Muscle fibre', 'tissue', 5e-5, ['dog_muscle_scene'], 'One muscle fibre is a single long cell that shortens when it is told to.', 'A fibre has hundreds of nuclei just under its membrane and is filled with contracting threads.', 'Each contracts when a nerve fires.', 'Not drawn in detail.', [['Cross-section', '≈ 1,700-1,800 µm² (vastus lateralis)']], cert='C2', refs=[A('10.2', '10-2-skeletal-muscle')], ext=[MUSC_ARC], human=[('skeletal_muscle_fiber', 'In people: the same cell.')])
N('dog_nmj', 'Neuromuscular junction', 'tissue', 2e-5, ['dog_muscle_scene'], 'Where a nerve meets a muscle fibre: the nerve releases acetylcholine, and the fibre contracts.', 'The nerve ending sits on the fibre. When a signal arrives, it releases a chemical messenger, acetylcholine. Press the button to see it.', 'Acetylcholine binds receptors on the muscle fibre, which opens channels, and the fibre fires and contracts. The chemical is then broken down so the signal ends.', 'The same chemical, receptors and mechanism are found across mammals, so the explorer\'s human card describes the dog too.', [['Messenger', 'acetylcholine']], cert='C1', refs=[A('10.3', '10-3-muscle-fiber-contraction-and-relaxation')], human=[('neuromuscular_junction', 'In people: the same junction.')])
N('dog_retina_scene', 'Inside the retina and tapetum', 'tissue', 5e-4, ['dog_retina'], 'A slice through the back of the eye: the sensing cells (rods and cones), a pigment layer, the shiny tapetum, and the dark choroid.', 'Light comes from the top. It passes through the nerve layers, is caught by the rods and cones, and what is not caught passes down to the tapetum and is reflected back up through the cells.',
  'The order of the layers is as in a dog\'s eye; the numbers of cells and the thickness are illustrative, except for the ratio of rods to cones (about 23 to 1 at the sharpest spot), drawn as about 20 to 1.', 'The tapetum has 9-20 cell layers; the scene draws 3.', [['Rod : cone ratio', '≈ 23 : 1']], cert='C2', refs=[R('36.5', '36-5-vision')], ext=[BEAGLE, WTAP], human=[('retina', 'In people: the same layers but no tapetum.')])
N('dog_rod', 'Rod cell', 'tissue', 6e-5, ['dog_retina_scene'], 'Rods are the cells for dim light, and dogs have a lot of them.', 'A rod is a long thin cell that catches single light particles. It cannot tell colours apart. Press the button to see retinal, the molecule that catches the light.',
  'Light flips a molecule called retinal inside a rod, and that starts a chain of events and a nerve signal. Dogs have about 23 rods for each cone at the sharpest spot.', 'The molecule that senses light in rods is rhodopsin, which has retinal bound to a protein. The same system is found in all vertebrate rods.', [['Rods per mm² (beagle, sharpest spot)', '≈ 501,000']], cert='C1', refs=[R('36.5', '36-5-vision')], ext=[BEAGLE], human=[('rod_cell', 'In people: the same cell.')])
N('dog_cone', 'Cone cell', 'tissue', 6e-5, ['dog_retina_scene'], 'Cones sense colour in bright light, and dogs have only two kinds.', 'A dog\'s two kinds of cone are most sensitive to blue-violet and to yellow-green.', 'The peaks are about 429 nm and about 555 nm. A person has three kinds.', 'A beagle retina had about 23,000-26,000 cones per mm² at the sharpest spot.', [['Cone peaks', '≈ 429 nm and ≈ 555 nm']], cert='C2', refs=[R('36.5', '36-5-vision')], ext=[BEAGLE], human=[('cone_cell', 'In people: the same cell; people have three kinds.')])
N('dog_tapetal_cells', 'Tapetal cells', 'tissue', 1e-5, ['dog_retina_scene'], 'Flat cells packed with tiny zinc rods that reflect light.', 'Layers of these cells form the shiny layer behind the retina.', 'There are 9-20 layers of them.', 'The cell sizes were not found.', [['Layers', '9-20']], cert='C2', ext=[WTAP, WCOMP], openq=['No molecule is attached here: the tapetum reflects light with zinc, and no zinc compound is in the explorer yet.'])
N('dog_rpe', 'Pigment layer (retinal pigment epithelium)', 'tissue', 1e-5, ['dog_retina_scene'], 'A thin layer of dark cells that serves the rods and cones and absorbs scattered light.', 'The layer sits behind the sensing cells.', 'In the part of the dog\'s eye above the tapetum this layer has no dark pigment.', 'Drawn as a thin sheet.', [['Role', 'support and light absorption']], cert='C2', ext=[WTAP])
